import{_ as t,o as a,c as s,a4 as o}from"./chunks/framework.B6zrJok8.js";const p=JSON.parse('{"title":"status","description":"","frontmatter":{},"headers":[],"relativePath":"cli/status.md","filePath":"cli/status.md","lastUpdated":null}'),r={name:"cli/status.md"};function i(n,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h1><p><strong>Main entry point for web producers.</strong> Run <code>make status</code> to see what&#39;s live, synced, ready to push, or needs a build—then pick a refresh and run an action (build, preview, push, etc.) from the same screen. Producers should also learn the other <a href="/cli/#producer-commands">producer commands</a> for full control: pull, build, preview, push, done, commit.</p><p>Unified refresh dashboard for the active brand. Shows a short, focused list and lets you pick a refresh and run an action. Refresh labels include the go-live time from the campaign (e.g. <strong>r1 - 3pm</strong>, <strong>r2 - 3am</strong>).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Last 14 days + future; summary + picker + actions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Show full list (no date window)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p>By default only refreshes from the <strong>last 14 days</strong> through <strong>all future</strong> dates are shown, so you don&#39;t scroll through a long list of past dates. Use <code>make status ALL=1</code> to see every refresh.</p><p>When the window is applied, status shows a reminder: <code>Showing last 14 days + future (N total). Use make status ALL=1 for full list.</code></p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>When you run <code>make status</code> in a terminal:</p><ol><li><strong>Legend</strong> — <code>LIVE = on site now · SYNCED = pushed · UPDATED = new data, needs rebuild · READY = ready to push · BUILD = needs build</code></li><li><strong>Summary line</strong> — e.g. <code>17 refreshes · 1 live · 2 synced · 1 ready · 13 to build</code></li><li><strong>Current selection</strong> — shows your active refresh (e.g. <code>Current: 2026-02-12 / r1 - 3pm</code>) or <code>Current: none</code>.</li><li><strong>Picker</strong> — one list of refreshes (↑↓ to move, Enter to select). Each row shows date, refresh label with time (e.g. <code>r1 - 3pm</code>), name, and status. Your active refresh is marked <strong>← active</strong>.</li><li><strong>Action</strong> — the selected refresh becomes your active refresh; choose: Build, Rebuild (ignore guards), Preview, Push, Generate email, or Commit.</li></ol><p>Picking a refresh sets it as active; subsequent commands (<code>make build</code>, <code>make preview</code>, etc.) use it automatically.</p><p>The list appears only once (in the picker), not as a table and then again in the picker.</p><h2 id="no-tty-fallback" tabindex="-1">No-TTY fallback <a class="header-anchor" href="#no-tty-fallback" aria-label="Permalink to &quot;No-TTY fallback&quot;">​</a></h2><p>When status runs without a TTY (e.g. piped output or CI), it falls back to a table view: Date, Name, Status, Next Step, plus registry summary and footer. The Next Step column shows go-live time when relevant (e.g. <code>→ live 2/12 12 AM</code>). No picker or action menu is shown.</p><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Condition</th></tr></thead><tbody><tr><td><code>LIVE</code></td><td>Synced and date is today (currently live on site)</td></tr><tr><td><code>SYNCED</code></td><td>Synced and date is not today (ready for future go-live)</td></tr><tr><td><code>UPDATED</code></td><td>Previously synced but new data detected since last sync (needs rebuild)</td></tr><tr><td><code>READY</code></td><td><code>ocapi-payload.json</code> exists, not yet pushed</td></tr><tr><td><code>BUILD</code></td><td><code>refresh.json</code> exists but no payload</td></tr></tbody></table><p>Status uses <strong>local</strong> sync state first (from <code>sync-config.json</code> in each refresh folder). When <strong>OCAPI is enabled</strong>, it also checks SFCC: if a refresh&#39;s campaign exists on the site, that row is shown as SYNCED or LIVE even when local state is missing (e.g. after deleting dev-env). Any state learned from SFCC is <strong>written back to local</strong> automatically, so the next run (or build guards) can use it without re-querying SFCC.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/cli/">CLI Reference</a> — all producer and dev commands</li><li><a href="/cli/pull.html">pull</a></li><li><a href="/cli/select.html">select</a> — direct switching (scripts, <code>DATE=</code>) without opening the dashboard</li><li><a href="/guides/producer-workflow.html">Producer workflow</a></li></ul>`,20)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
